// Small, deterministic teaching models. These do not replace the Python benchmarks.
export function rng(seed=42){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return((t^(t>>>14))>>>0)/4294967296;};}
export function normal(random){return Math.sqrt(-2*Math.log(Math.max(random(),1e-15)))*Math.cos(2*Math.PI*random());}
export const sum=a=>a.reduce((s,x)=>s+x,0);
export const mean=a=>sum(a)/a.length;
export function softmax(a){const m=Math.max(...a),b=a.map(x=>Math.exp(x-m)),s=sum(b);return b.map(x=>x/s);}
export const ess=w=>1/sum(w.map(x=>x*x));
export function scalarMoments(x,w=x.map(()=>1/x.length)){const mu=sum(x.map((v,i)=>v*w[i]));return{mean:mu,variance:sum(x.map((v,i)=>w[i]*(v-mu)**2))};}
export function moments(x,w=x.map(()=>1/x.length)){const d=x[0].length,mu=Array(d).fill(0),cov=Array.from({length:d},()=>Array(d).fill(0));x.forEach((v,i)=>v.forEach((a,j)=>mu[j]+=a*w[i]));x.forEach((v,i)=>v.forEach((a,j)=>v.forEach((b,k)=>cov[j][k]+=w[i]*(a-mu[j])*(b-mu[k]))));return{mean:mu,cov};}
export function root2(a,inverse=false,floor=1e-10){const theta=.5*Math.atan2(2*a[0][1],a[0][0]-a[1][1]),c=Math.cos(theta),s=Math.sin(theta),tr=(a[0][0]+a[1][1])/2,delta=Math.hypot((a[0][0]-a[1][1])/2,a[0][1]);let hi=Math.sqrt(Math.max(floor,tr+delta)),lo=Math.sqrt(Math.max(floor,tr-delta));if(inverse){hi=1/hi;lo=1/lo;}return[[c*c*hi+s*s*lo,c*s*(hi-lo)],[c*s*(hi-lo),s*s*hi+c*c*lo]];}
export const rowMultiply=(x,a)=>[x[0]*a[0][0]+x[1]*a[1][0],x[0]*a[0][1]+x[1]*a[1][1]];
export function eigen2(x,w,floor=1e-10){const reference=moments(x),target=moments(x,w),z=x.map(p=>p.map((v,j)=>v-reference.mean[j])),white=z.map(p=>rowMultiply(p,root2(reference.cov,true,floor))),colored=white.map(p=>rowMultiply(p,root2(target.cov,false,floor))),y=colored.map(p=>p.map((v,j)=>v+target.mean[j]));return{y,z,white,colored,reference,target};}
export function eigen1(x,w,floor=1e-10){const source=scalarMoments(x),target=scalarMoments(x,w),scale=Math.sqrt(Math.max(target.variance,floor)/Math.max(source.variance,floor));return x.map(v=>target.mean+(v-source.mean)*scale);}
export function sampleIndices(w,method,random){const n=w.length,cdf=[];let total=0;for(const v of w){total+=v;cdf.push(total);}const lookup=u=>{let i=0;while(i<n-1&&u>=cdf[i])i++;return i;};if(method==='residual'){const indices=[],residual=w.map((v,i)=>{const copies=Math.floor(n*v);for(let j=0;j<copies;j++)indices.push(i);return n*v-copies;});const remaining=n-indices.length;if(remaining){const rsum=sum(residual),rcdf=[];let c=0;residual.forEach(v=>{c+=v/rsum;rcdf.push(c);});for(let j=0;j<remaining;j++){const u=random();let i=0;while(i<n-1&&u>=rcdf[i])i++;indices.push(i);}}return indices;}const start=method==='systematic'?random():0;return Array.from({length:n},(_,i)=>lookup(method==='systematic'?(i+start)/n:method==='stratified'?(i+random())/n:random()));}
export function wasserstein1(x,w,y,v=y.map(()=>1/y.length)){const events=x.map((p,i)=>[p,w[i]]).concat(y.map((p,i)=>[p,-v[i]])).sort((a,b)=>a[0]-b[0]);let c=0,result=0;for(let i=0;i<events.length-1;i++){c+=events[i][1];result+=Math.abs(c)*(events[i+1][0]-events[i][0]);}return result;}
export function mmd2(x,w,y,v=y.map(()=>1/y.length)){const bandwidth=Math.max(1e-6,Math.sqrt(scalarMoments(x,w).variance)),kernel=(a,b)=>Math.exp(-.5*((a-b)/bandwidth)**2);let result=0;for(let i=0;i<x.length;i++)for(let j=0;j<x.length;j++)result+=w[i]*w[j]*kernel(x[i],x[j]);for(let i=0;i<y.length;i++)for(let j=0;j<y.length;j++)result+=v[i]*v[j]*kernel(y[i],y[j]);for(let i=0;i<x.length;i++)for(let j=0;j<y.length;j++)result-=2*w[i]*v[j]*kernel(x[i],y[j]);return Math.max(0,result);}
export function mixture(n=128,separation=3,mass=.65,seed=41){const random=rng(seed),x=Array.from({length:n},(_,i)=>(i%2?separation:-separation)+.45*normal(random));const w=x.map((_,i)=>(i%2?mass:1-mass)/(n/2));return{x,w};}
export function gradientToy(theta,fn='sin'){const{x}=mixture(64,2.6,.5,19),w=softmax(x.map(v=>theta*v)),mom=scalarMoments(x,w),source=scalarMoments(x),y=eigen1(x,w),f=fn==='square'?v=>v*v:Math.sin,df=fn==='square'?v=>2*v:Math.cos;const third=sum(x.map((v,i)=>w[i]*(v-mom.mean)**3)),dy=x.map(v=>mom.variance+(v-source.mean)*third/(2*Math.sqrt(mom.variance*source.variance)));const original=sum(x.map((v,i)=>w[i]*f(v))),originalGradient=sum(x.map((v,i)=>w[i]*f(v)*(v-mom.mean)));return{value:mean(y.map(f)),gradient:mean(y.map((v,i)=>df(v)*dy[i])),original,originalGradient,x,w,y};}
export function kalmanReference(observations,r=.8){let m=0,p=1,ll=0;const means=[],variances=[];for(const y of observations){const mp=.8*m,pp=.64*p+.25,s=pp+r*r,k=pp/s;ll+=-.5*(Math.log(2*Math.PI*s)+(y-mp)**2/s);m=mp+k*(y-mp);p=(1-k)*pp;means.push(m);variances.push(p);}return{means,variances,loglik:ll};}
export function filterToy(n=128,method='systematic',r=.8,seed=43){const dataRandom=rng(seed),particleRandom=rng(seed+700);let state=normal(dataRandom);const truth=[],observations=[];for(let t=0;t<40;t++){state=.8*state+.5*normal(dataRandom);truth.push(state);observations.push(state+r*normal(dataRandom));}const exact=kalmanReference(observations,r);let x=Array.from({length:n},()=>normal(particleRandom)),w=Array(n).fill(1/n),loglik=0;const means=[],variances=[],effective=[],flags=[];for(let t=0;t<40;t++){x=x.map(v=>.8*v+.5*normal(particleRandom));const lw=x.map((v,i)=>Math.log(w[i])-.5*(Math.log(2*Math.PI*r*r)+(observations[t]-v)**2/(r*r))),m=Math.max(...lw),normalizer=m+Math.log(sum(lw.map(v=>Math.exp(v-m))));loglik+=normalizer;w=lw.map(v=>Math.exp(v-normalizer));const mom=scalarMoments(x,w);means.push(mom.mean);variances.push(mom.variance);effective.push(ess(w));const resample=method!=='none'&&effective[t]<.5*n;flags.push(resample);if(resample){x=method==='eigen'?eigen1(x,w):sampleIndices(w,method,particleRandom).map(i=>x[i]);w=Array(n).fill(1/n);}}return{truth,observations,means,variances,effective,flags,exact,loglik,rmse:Math.sqrt(mean(means.map((v,i)=>(v-truth[i])**2))),posteriorError:Math.sqrt(mean(means.map((v,i)=>(v-exact.means[i])**2)))};}
